    roundedBox(1.08, 1.02, 0.085, 0.028, M.yellowDark, 0, 0, 0, transferBay.innerShutter);
    roundedBox(0.94, 0.88, 0.06, 0.022, M.machineDark, 0, 0, 0.05, transferBay.innerShutter);
